g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "lp-gp-risk-table",
  "x": 64, "y": 180, "width": 1152, "height": 272,
  "strict_grid": true,
  "column_widths": [276, 438, 438],
  "row_heights": [44, 76, 76, 76],
  "style": {
    "font_family": "Calibri",
    "font_size": 20,
    "header_fill": "#003657",
    "header_text": "#FBF8F2",
    "body_text": "#1E1E1E",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 16, "right": 16, "top": 6, "bottom": 6},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#D6CFC2", "width": 1},
        "bottom": {"style": "solid", "color": "#D6CFC2", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "", "align": "l"},
    {"text": "LP", "bold": true, "align": "l"},
    {"text": "GP", "bold": true, "align": "l", "fill": "#0055FF"}
  ],
  "rows": [
    [
      {"text": "Modeled receipts", "bold": true, "color": "#003657"},
      {"text": "Investment distributions"},
      {"text": "Management fees and carry"}
    ],
    [
      {"text": "Performance exposure", "bold": true, "color": "#003657", "fill": "#F1ECE2"},
      {"text": "IRR and NPV change with growth and timing", "fill": "#F1ECE2"},
      {"text": "Carry changes with fund performance", "fill": "#F1ECE2"}
    ],
    [
      {"text": "Additional context", "bold": true, "color": "#003657"},
      {"text": "Capital committed before returns are realised"},
      {"text": "About $500m own-capital commitment; operating costs"}
    ]
  ]
}
